### 2. 游戏状态广播
```javascript
broadcast(msg) {
    const data = JSON.stringify(msg);
    this.players.forEach((p, pid) => {
        if (p.ws.readyState === WebSocket.OPEN) {
            p.ws.send(data);
        }
    });
}

broadcastGameState() {
    for (const [playerId, player] of this.players) {
        player.ws.send(JSON.stringify({
            type: 'gameState',
            gameState: this.getPlayerGameState(playerId)
        }));
    }
}
```

### 3. AI选牌策略
```javascript
selectAICards(hand) {
    const lastPlay = this.gameState.lastPlay;

    if (!lastPlay || this.gameState.lastPlayer === currentPlayerId) {
        // 领出：出最小的单张
        return [hand[0]];
    }

    // 跟牌：寻找能压过的最小牌组合
    if (lastPlay.type === 'single') {
        const card = hand.find(c => c.value > lastPlay.value);
        return card ? [card] : null;
    }

    // 其他牌型...
}
